{
  pkgs,
  config,
  edgeGap,
  laptopScale,
  hyprDpmsPhysical,
  ...
}:
let
  lib = pkgs.lib;
  inherit (lib.generators) mkLuaInline;

  # Hyprland's $variable mechanism is a Hyprlang-parser feature; the Lua config
  # backend has no equivalent, so resolve these in Nix and inline the values.
  mainMod = "SUPER";
  terminal = "ghostty";
  menu = "walker";

  # Bind helpers. In the Lua config every `bind` is `hl.bind(keys, dispatcher,
  # opts?)`, keys joined with " + ". Two ways to render the dispatcher via
  # mkLuaInline:
  #   exec  - run a shell command; `hl.dsp.exec_cmd` is Hyprlang `exec`.
  #           (`hl.dsp.exec_raw`/Hyprlang `execr` runs a *program* without a
  #           shell. Neither is a dispatcher; those go through `hl.dsp.*` below.)
  #   dsp   - a structured dispatcher, e.g. hl.dsp.focus({ direction = "left" }),
  #           hl.dsp.window.close(), hl.dsp.window.move({ workspace = 1 }).
  # [=[ ... ]=] long brackets let shell commands keep their quotes and `]]`.
  exec = keys: cmd: {
    _args = [
      keys
      (mkLuaInline "hl.dsp.exec_cmd([=[${cmd}]=])")
    ];
  };
  execOpts = keys: cmd: opts: {
    _args = [
      keys
      (mkLuaInline "hl.dsp.exec_cmd([=[${cmd}]=])")
      opts
    ];
  };
  dsp = keys: luaExpr: {
    _args = [
      keys
      (mkLuaInline luaExpr)
    ];
  };
  # Structured dispatcher with bind options (mouse drag/resize need
  # { mouse = true }).
  dspOpts = keys: luaExpr: opts: {
    _args = [
      keys
      (mkLuaInline luaExpr)
      opts
    ];
  };

  wsKeys = [
    "1"
    "2"
    "3"
    "4"
    "5"
    "6"
    "7"
    "8"
    "9"
    "0"
  ];
  workspaceBinds = lib.imap1 (
    i: k: dsp "${mainMod} + ${k}" "hl.dsp.focus({ workspace = ${toString i} })"
  ) wsKeys;
  moveToWorkspaceBinds = lib.imap1 (
    i: k: dsp "${mainMod} + SHIFT + ${k}" "hl.dsp.window.move({ workspace = ${toString i} })"
  ) wsKeys;
in
{
  enable = true;
  package = pkgs.hyprland;
  configType = "lua";
  settings = {
19:  # Bind helpers. In the Lua config every `bind` is `hl.bind(keys, dispatcher,
47:  # Structured dispatcher with bind options (mouse drag/resize need
91:        resolve_binds_by_sym = true;
306:    bind =
368:        # Mouse drag/resize (Hyprlang bindm).
373:        # (Hyprlang bindel).
399:        # Media and lid switch: work on the lock screen (Hyprlang bindl).

