    i: k: dsp "${mainMod} + SHIFT + ${k}" "hl.dsp.window.move({ workspace = ${toString i} })"
  ) wsKeys;
in
{
  enable = true;
  package = pkgs.hyprland;
  configType = "lua";
  settings = {
19:  # Bind helpers. In the Lua config every `bind` is `hl.bind(keys, dispatcher,
47:  # Structured dispatcher with bind options (mouse drag/resize need
91:        resolve_binds_by_sym = true;
306:    bind =
368:        # Mouse drag/resize (Hyprlang bindm).
373:        # (Hyprlang bindel).
399:        # Media and lid switch: work on the lock screen (Hyprlang bindl).

content.content:
        kb_layout = "us";
        kb_variant = "colemak";
        kb_options = "ctrl:nocaps,ctrl:swapcaps";
      }
    ];

    # exec-once equivalents. The module already emits a hyprland.start hook for
    # the systemd/D-Bus activation env, so we only add our own programs. The
    # xrdb -merge ahead of mako/elephant/everything-else is load-bearing: the X
    # server's resource database only exists across the lifetime of its
    # Xwayland instance, so anything `xrdb`-loaded before Hyprland starts pushes
    # values into a DB the compositor's Xwayland never reads. Loading it from
    # hyprland.start makes it the first thing to touch X for this session.
    on = [
      {
        _args = [
          "hyprland.start"
          (mkLuaInline ''
            function()
              hl.exec_cmd("${pkgs.xorg.xrdb}/bin/xrdb -merge ${config.home.homeDirectory}/.Xresources")
              hl.exec_cmd("mako")
              hl.exec_cmd("hypr-fullscreen-inhibit")
              hl.exec_cmd("elephant")
            end'')
        ];
      }

      # Pin Vesktop to workspace 8. Vesktop is the user's Discord client and
      # should live on ws8 regardless of where it was launched from. WM_CLASS is
      # "Vesktop" (capital V) -- from the StartupWMClass in
      # /nix/store/.../share/applications/vesktop.desktop. Static windowrulev2
      # would also work; using a window.open handler keeps the per-window
      # behaviour colocated with the rest of this file's hooks.
      {
        _args = [
          "window.open"
          (mkLuaInline ''
            function(w)
              if w.class ~= "Vesktop" then return end
              hl.dispatch(hl.dsp.window.move({ workspace = 8, window = w }))
            end'')
        ];
      }

      # Float Zen's extension popups (Bitwarden's is the one that prompted this).
      #
      # This cannot be a window_rule. `float` is a *static* effect: Hyprland
      # evaluates it once at map time against initialTitle/initialClass and never
      # again. Gecko maps the popup as an ordinary browser window and only then
      # renames it to "Extension: (...)", so there is no moment at which a title
      # matcher and the static pass coincide. Upstream closed the request to make
      # `float` dynamic as not planned (hyprwm/Hyprland#3835; #602 is the same
      # bug against Tree Style Tabs), and the wiki's own answer is to dispatch
      # from an event listener -- which is this.
      #
      # Guards, both load-bearing: `class` because any window may put
      # "Extension: " in its title, and `address` because window.title is a
      # global event, not a per-window one. Covered by tests/hyprland-zen-popup.sh.
      #
      # zenPopupSubs keys the live subscriptions by address so the window.close
      # hook below can drop one that never fired. Deliberately a global: each
      # `on` renders as its own top-level hl.on call, so the two hooks share no
      # local scope.
      {
        _args = [
          "window.open"
          (mkLuaInline ''
            function(w)
              if w.class ~= "zen-beta" then return end
              zenPopupSubs = zenPopupSubs or {}
              local subs = zenPopupSubs
              if subs[w.address] then subs[w.address]:remove() end
              local sub
              sub = hl.on("window.title", function(tw)
                if tw.address ~= w.address then return end
                if not tw.title:match("^Extension: ") then return end
                sub:remove()
                subs[w.address] = nil
                hl.dispatch(hl.dsp.window.float({ action = "enable", window = tw }))
              end)
              subs[w.address] = sub
            end'')
        ];
      }

      # A Zen window that never turns out to be a popup would otherwise keep its
      # window.title subscription for the compositor's lifetime. Hyprland
      # addresses are recycled heap pointers, so a stale subscription does not
      # just leak -- it fires for whichever window inherits the address next.
      {
        _args = [
          "window.close"
          (mkLuaInline ''
            function(w)
              local subs = zenPopupSubs
              if not subs then return end
              local sub = subs[w.address]
              if sub then
                sub:remove()
                subs[w.address] = nil
              end
            end'')
        ];
      }
    ];

    bind =
      [
        (exec "${mainMod} + return" terminal)
        (dsp "${mainMod} + SHIFT + W" "hl.dsp.window.close()")
        (exec "${mainMod} + SHIFT + E" "hyprland-graceful-exit")
